begin;
create table if not exists public.mme_enterprise_risks(risk_id uuid primary key default gen_random_uuid(),risk_code text not null unique,title text not null,description text not null,risk_domain text not null check(risk_domain in('financial','operational','technology','cybersecurity','vendor','compliance','people','facilities','reputation','business_continuity')),entity_id uuid references public.mme_financial_reporting_entities(entity_id),department text not null,owner_auth_user_id uuid not null,likelihood smallint not null check(likelihood between 1 and 5),impact smallint not null check(impact between 1 and 5),inherent_score smallint generated always as(likelihood*impact) stored,residual_likelihood smallint check(residual_likelihood between 1 and 5),residual_impact smallint check(residual_impact between 1 and 5),residual_score smallint generated always as(coalesce(residual_likelihood,likelihood)*coalesce(residual_impact,impact)) stored,risk_status text not null default 'identified' check(risk_status in('identified','assessing','mitigating','accepted','monitoring','closed')),mitigation_plan text,review_due_date date,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists mme_enterprise_risks_queue_idx on public.mme_enterprise_risks(risk_status,risk_domain,residual_score desc);
create table if not exists public.mme_risk_assessments(assessment_id uuid primary key default gen_random_uuid(),risk_id uuid not null references public.mme_enterprise_risks(risk_id),assessed_likelihood smallint not null check(assessed_likelihood between 1 and 5),assessed_impact smallint not null check(assessed_impact between 1 and 5),assessment_score smallint generated always as(assessed_likelihood*assessed_impact) stored,assessment_notes text not null,assessed_by_auth_user_id uuid not null,assessed_at timestamptz not null default now(),next_review_date date);
create table if not exists public.mme_business_continuity_plans(plan_id uuid primary key default gen_random_uuid(),plan_code text not null unique,title text not null,department text not null,critical_process text not null,plan_owner_auth_user_id uuid not null,plan_status text not null default 'draft' check(plan_status in('draft','under_review','approved','active','retired')),recovery_time_objective_minutes integer not null check(recovery_time_objective_minutes>0),recovery_point_objective_minutes integer not null check(recovery_point_objective_minutes>=0),activation_criteria text not null,alternate_procedure text not null,communications_plan text,dependencies jsonb not null default '[]'::jsonb,last_tested_at timestamptz,next_test_due date,approved_by_auth_user_id uuid,approved_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(approved_by_auth_user_id is null or approved_by_auth_user_id<>created_by_auth_user_id));
create table if not exists public.mme_continuity_incidents(incident_id uuid primary key default gen_random_uuid(),incident_reference text not null unique,title text not null,incident_type text not null check(incident_type in('cyber','technology','facility','vendor','staffing','financial','utility','other')),severity text not null check(severity in('low','medium','high','critical')),incident_status text not null default 'reported' check(incident_status in('reported','triaged','contained','recovering','resolved','closed')),impact_summary text not null,affected_department text,affected_process text,commander_auth_user_id uuid,reported_by_auth_user_id uuid not null,started_at timestamptz not null default now(),resolved_at timestamptz,lessons_learned text,created_at timestamptz not null default now());
create table if not exists public.mme_continuity_incident_events(event_id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.mme_continuity_incidents(incident_id),event_type text not null check(event_type in('reported','triaged','contained','recovery_started','resolved','closed','note_added')),from_status text,to_status text,note text,actor_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_continuity_exercises(exercise_id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.mme_business_continuity_plans(plan_id),exercise_type text not null check(exercise_type in('tabletop','walkthrough','simulation','full_recovery')),scheduled_at timestamptz not null,completed_at timestamptz,exercise_status text not null default 'scheduled' check(exercise_status in('scheduled','in_progress','passed','failed','cancelled')),actual_recovery_minutes integer check(actual_recovery_minutes>=0),actual_data_loss_minutes integer check(actual_data_loss_minutes>=0),findings text,corrective_actions text,facilitator_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_critical_vendor_risks(vendor_risk_id uuid primary key default gen_random_uuid(),vendor_name text not null,vendor_service text not null,criticality text not null check(criticality in('low','medium','high','critical')),risk_status text not null default 'under_review' check(risk_status in('under_review','approved','watch','restricted','exited')),single_point_of_failure boolean not null default false,alternative_provider text,assessment_summary text not null,owner_auth_user_id uuid not null,next_review_date date,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create or replace function public.mme_continuity_transition_incident(p_incident uuid,p_status text,p_note text,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$declare i public.mme_continuity_incidents%rowtype;v_event text;begin if p_status not in('triaged','contained','recovering','resolved','closed') then raise exception 'invalid_incident_status';end if;select * into i from public.mme_continuity_incidents where incident_id=p_incident for update;if not found then raise exception 'incident_not_found';end if;if i.incident_status in('resolved','closed') and p_status not in('closed') then raise exception 'incident_terminal';end if;v_event:=case p_status when 'triaged' then 'triaged' when 'contained' then 'contained' when 'recovering' then 'recovery_started' when 'resolved' then 'resolved' else 'closed' end;insert into public.mme_continuity_incident_events(incident_id,event_type,from_status,to_status,note,actor_auth_user_id) values(p_incident,v_event,i.incident_status,p_status,left(coalesce(p_note,''),2000),p_actor);update public.mme_continuity_incidents set incident_status=p_status,resolved_at=case when p_status in('resolved','closed') then now() else resolved_at end,lessons_learned=case when p_status in('resolved','closed') and coalesce(p_note,'')<>'' then left(p_note,4000) else lessons_learned end where incident_id=p_incident;return p_incident;end$$;
do $$declare t text;begin foreach t in array array['mme_enterprise_risks','mme_risk_assessments','mme_business_continuity_plans','mme_continuity_incidents','mme_continuity_incident_events','mme_continuity_exercises','mme_critical_vendor_risks'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on function public.mme_continuity_transition_incident(uuid,text,text,uuid) from public,anon,authenticated;
grant execute on function public.mme_continuity_transition_incident(uuid,text,text,uuid) to service_role;
commit;